/* 无构建依赖的交互原型；仅操作独立命名空间内的本地演示数据。 */
const ADMIN = document.body.dataset.app === 'admin';
const STORE = 'wutong-prototype-v1';
const icons = {home:'M3 10 12 3l9 7v10H4V10 M9 20v-7h6v7',activity:'M5 5h14v16H5z M8 3v4 M16 3v4 M5 10h14 M9 14h2 M14 14h2',idle:'M4 7h16l-1 13H5L4 7 M8 7V5a4 4 0 0 1 8 0v2',lost:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',social:'M21 11a9 8 0 0 1-9 8H5l-3 3V11a9 8 0 0 1 19 0 M7 10h10 M7 14h6',ai:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3V4 M12 6v15',code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',bell:'M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3V9 M10 21h4',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-2a8 8 0 0 1 16 0v2',arrow:'M4 12h16 m-6-6 6 6-6 6',down:'m6 9 6 6 6-6',plus:'M12 4v16 M4 12h16',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',pin:'M12 22s8-8 8-13a8 8 0 0 0-16 0c0 5 8 13 8 13 M12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',heart:'M12 21 3 12C-3 5 7-1 12 6c5-7 15-1 9 6l-9 9',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4 M8 12l3 3 5-6',chart:'M4 3v18h18 M8 16v-5 M13 16V7 M18 16V4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',logout:'M9 3H3v18h6 M10 12h12 m-5-5 5 5-5 5',menu:'M3 6h18 M3 12h18 M3 18h18',close:'m5 5 14 14 M19 5 5 19',check:'m4 12 5 5 11-11',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',send:'m2 3 20 9-20 9 4-9-4-9 M6 12h16'};
const icon = name => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[name] || icons.file}"/></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = x => JSON.parse(JSON.stringify(x));
let state;
try { state = JSON.parse(localStorage.getItem(STORE)); } catch {}
if (!state || state.version !== 1) state={version:1,theme:'light',favorites:[],signups:[],appointments:[],claims:[],publications:[],posts:[],likes:[],comments:{},chat:[],ai:[],wrong:clone(CAMPUS.wrong),profile:{name:'林同学',bio:'认真学习，也认真感受校园的每一天。'},read:false,audits:{},reports:{},users:{},settings:{},notices:[],role:'super'};
let filter='全部', query='', profileTab='我的发布', aiScene='学习答疑', chatPerson='陈同学', toastTimer, lastFocus;
const app=document.getElementById('app'), modal=document.getElementById('modal');
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('当前浏览器无法保存本地数据，本次操作仅在此会话有效');}}
function toast(message){const box=document.getElementById('toast');box.textContent=message;box.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('show'),3000);}
function href(path){return `#/${path}`;}
function go(path){if(location.hash===href(path)) render();else location.hash=href(path);}
function route(){return decodeURIComponent(location.hash.replace(/^#\/?/,'')) || (ADMIN?'dashboard':'home');}
function link(path,label,cls='btn',ico=''){return `<a class="${cls}" href="${href(path)}">${ico?icon(ico):''}${label}</a>`;}
function btn(label,action,extra='',cls='btn'){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function tag(text,cls=''){return `<span class="tag ${cls}">${esc(text)}</span>`;}
function avatar(name='林',cls=''){return `<span class="avatar ${cls}">${esc(name[0])}</span>`;}
function empty(text='暂无相关内容',sub='换个关键词试试，或发布你的第一条内容。'){return `<div class="empty">${icon('book')}<h3>${text}</h3><p>${sub}</p></div>`;}
function field(label,name,type='text',value='',options){return `<label class="field"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" ${options||''}>${esc(value)}</textarea>`:type==='select'?`<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${options||''}>`}</label>`;}
function head(title,sub,action='',eyebrow='CAMPUS LIFE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const studentNav=[['校园生活',[['home','home','校园首页'],['activity','activity','校园活动'],['idle','idle','闲置互换'],['lostfound','lost','失物招领'],['social','social','动态广场']]],['学习与成长',[['ai/chat','ai','AI 学习助手'],['ai/code','code','代码纠错'],['ai/wrong','book','我的错题本']]],['我的校园',[['notice','file','校园公告'],['message','bell','消息中心'],['chat','social','私信聊天'],['profile','user','个人中心']]]];
const adminNav=[['工作概览',[['dashboard','chart','数据总览'],['user','user','用户管理']]],['内容与安全',[['audit/activity','activity','活动审核'],['audit/idle','idle','闲置审核'],['audit/lostfound','lost','失物审核'],['audit/post','social','动态审核'],['content','file','内容管理'],['ai/audit','shield','AI 内容审核'],['report','shield','举报处理'],['notice','bell','公告管理']]],['系统设置',[['ai/config','ai','AI 服务配置'],['ai/logs','code','AI 调用日志'],['system/config','settings','系统配置'],['system','user','管理员管理']]]];
function shell(body,title){const current=route(),nav=ADMIN?adminNav:studentNav;document.body.classList.toggle('admin',ADMIN);document.documentElement.dataset.theme=state.theme;
app.innerHTML=`<aside class="sidebar" id="sidebar"><a href="${href(ADMIN?'dashboard':'home')}" class="brand"><span class="brandmark">w</span><span><b>梧桐校园</b><small>${ADMIN?'CAMPUS ADMIN':'WUTONG CAMPUS'}</small></span></a><nav class="side-scroll" aria-label="主导航">${nav.map(([group,items])=>`<div class="nav-group">${group}</div>${items.filter(([p])=>!ADMIN||state.role==='super'||!p.startsWith('system')).map(([path,ico,label])=>`<a href="${href(path)}" class="nav-link ${current===path||(path!=='home'&&path!=='system'&&current.startsWith(path+'/'))?'active':''}">${icon(ico)}${label}</a>`).join('')}`).join('')}</nav><div class="sidebar-bottom">${!ADMIN?`<div class="side-ai"><b>让灵感，多一个回应</b><p>学习上的小困惑，交给 AI 一起想。</p>${link('ai/chat','开启一段对话','text-btn')} ${icon('arrow')}</div>`:''}<a class="user-chip" href="${href(ADMIN?'login':'profile')}">${avatar(ADMIN?'管':state.profile.name)}<span><b>${ADMIN?(state.role==='super'?'超级管理员':'内容管理员'):esc(state.profile.name)}</b><small>${ADMIN?'管理工作台 · 演示身份':'计算机科学与技术 · 2023 级'}</small></span></a></div></aside><div class="main"><header class="topbar">${btn(icon('menu'),'menu','aria-label="切换导航"','icon-btn mobile-menu')}<div class="breadcrumb">${ADMIN?'管理工作台':'我的校园'} <span style="padding:0 10px">/</span> <b>${title}</b></div><form class="top-search" data-form="search">${icon('lost')}<input name="q" aria-label="搜索校园内容" placeholder="${ADMIN?'搜索当前管理页面':'搜索活动、闲置、校园动态…'}" value="${esc(query)}"><kbd style="font-size:10px;color:var(--muted)">↵</kbd></form><div class="top-actions">${btn(icon('sun'),'theme','aria-label="切换明暗主题"','icon-btn')}${link(ADMIN?'report':'message',icon('bell'),'icon-btn '+(!state.read?'dot':''))}${ADMIN?'<a class="btn small" href="index.html">学生端</a>':btn(icon('plus')+' 发布','publish-menu','','btn primary small')}</div></header><main class="content" id="main">${body}<footer class="footer"><span>梧桐校园 · 让校园生活更有连接</span><span>交互原型 · 虚构演示数据 <a href="#/sitemap">页面导航</a><a href="${ADMIN?'index.html':'admin.html'}">${ADMIN?'学生端':'管理端'}</a><button class="text-btn" data-action="reset">重置演示</button></span></footer></main></div>`;
}
function getItems(type){return [...state.publications.filter(p=>p.type===type),...(type==='social'?state.posts:[]),...(CAMPUS[type]||[])];}
function searchable(x){return [x.title,x.subtitle,x.category,x.host,x.location,x.description].filter(Boolean).join(' ');}
function visibleItems(type){return getItems(type).filter(x=>!['待审核','已驳回','已下架'].includes(x.status));}
function getItem(type,id){return getItems(type).find(x=>String(x.id)===String(id));}
function card(item,type){return `<a class="item" href="${href(type+'/detail/'+item.id)}"><div class="cover"><img src="assets/images/${esc(item.image)}" alt="${esc(item.title)}" loading="lazy">${tag(item.category)}<span class="corner">${item.status}</span></div><div class="item-body"><h3>${esc(item.title)}</h3><div class="item-meta">${icon(type==='activity'?'clock':'pin')}${esc(type==='activity'?item.time:item.location)}</div><div class="item-meta">${icon(type==='activity'?'pin':'idle')}${esc(type==='activity'?item.location:type==='idle'?item.exchange:item.time)}</div><div class="item-bottom"><span>${type==='activity'?`<span class="avatar-stack"><span>林</span><span>陈</span><span>周</span></span>${item.count} 人已报名`:esc(item.host)}</span><span>${type==='activity'?'一起去看看':'查看详情'} ↗</span></div></div></a>`;}
function listCards(items,type,cls=''){return `<div class="cards ${cls}">${items.length?items.map(x=>card(x,type)).join(''):empty()}</div>`;}
function home(){return head(`你好，${esc(state.profile.name)} <span style="color:#acb398;font-weight:400">/</span>`, '新的一天，从这里发现校园的美好。',`<div class="date-label"><b>2026 年 9 月 17 日 · 星期四</b><br>秋季学期 · 第 3 周</div>`,'A LITTLE CONNECTION, EVERY DAY')+`<section class="hero"><div class="hero-content"><div class="eyebrow">YOUR CAMPUS, YOUR STORY</div><h2>在梧桐，遇见<br>校园生活的更多可能。</h2><p>一起学习、分享闲置、发现同好。让每一份热爱都有回应。</p>${link('activity','探索校园活动 '+icon('arrow'),'btn accent')}</div><span class="hero-index">AUTUMN / 2026</span></section><div class="quick-grid">${[['activity','activity','校园活动','把热爱变成一次相遇'],['idle','idle','闲置互换','让好物继续发光'],['lostfound','lost','失物招领','帮每份牵挂找到归处'],['social','social','动态广场','收藏校园里的小美好']].map(([p,i,t,s])=>`<a class="quick" href="${href(p)}"><span class="symbol">${icon(i)}</span><span><strong>${t}</strong><small>${s}</small></span><span class="arrow">›</span></a>`).join('')}</div><div class="home-columns"><section><div class="section-title"><h2>校园新鲜事 <small>WHAT'S HAPPENING</small></h2>${link('activity','发现更多 ↗','text-btn')}</div><div class="tabs line">${['为你推荐','校园活动','闲置互换','失物招领'].map(t=>btn(t,'home-tab',`data-value="${t}"`, 'tab '+((filter==='全部'&&t==='为你推荐')||filter===t?'active':''))).join('')}</div>${listCards(filter==='闲置互换'?CAMPUS.idle.slice(0,2):filter==='失物招领'?CAMPUS.lostfound:CAMPUS.activity.slice(0,2),filter==='闲置互换'?'idle':filter==='失物招领'?'lostfound':'activity','two')}<div class="banner-strip"><span class="symbol">${icon('social')}</span><div><h3>今天，你想分享什么？</h3><p>一张晚霞，一点灵感，或是一个想认识新朋友的念头。</p></div>${link('social','去广场逛逛 ↗','text-btn')}</div><div class="section-title spaced"><h2>让闲置，遇见新主人</h2>${link('idle','全部好物 ↗','text-btn')}</div>${listCards(CAMPUS.idle.slice(0,2),'idle','two')}</section><aside><div class="panel study-panel"><div class="big-spark">✧</div><div class="eyebrow">YOUR STUDY BUDDY</div><h3>今天，也进步一点点</h3><p>不懂的题、卡住的代码，一起解开。</p><div class="study-stat"><strong>${state.wrong.filter(x=>x.status==='待复习').length}</strong> 道错题等待复习</div><div class="progress"><i style="width:66%"></i></div>${link('ai/chat','和 AI 聊聊 '+icon('arrow'),'btn')}</div><div class="panel"><div class="section-title"><h3 style="margin:0">校园公告</h3>${link('notice','全部 ↗','text-btn')}</div>${CAMPUS.notices.map(n=>`<a class="notice-row" href="${href('notice/detail/'+n.id)}"><span class="notice-bullet"></span><span><b>${n.title}</b><small>${n.date.slice(5).replace('-','.')} · ${n.type}</small></span></a>`).join('')}</div><div class="panel"><div class="section-title"><h3 style="margin:0">我的校园日历</h3><small>九月</small></div><div class="weekly">${['一','二','三','四','五','六','日'].map((d,i)=>`<span>${d}<b class="${i===3?'today':''}">${14+i}</b></span>`).join('')}</div><div class="notice-row"><span class="notice-bullet"></span><span><b>${state.signups.length?'已报名活动即将开始':'还没有活动安排'}</b><small>${state.signups.length?'查看报名记录，别错过精彩':'去发现一场感兴趣的活动吧'}</small></span></div>${link('activity/my-signup','查看我的报名 ↗','text-btn')}</div></aside></div>`;}
const labels={activity:'校园活动',idle:'闲置互换',lostfound:'失物招领'};
function catalog(type){let items=visibleItems(type);if(filter!=='全部')items=items.filter(x=>x.category===filter);if(query)items=items.filter(x=>searchable(x).includes(query));const cats=type==='activity'?['全部','文艺','运动','公益','学习']:type==='idle'?['全部','数码','出行','运动']:['全部','寻找失物','拾到物品'];return head(labels[type],{activity:'让热爱相遇，让每个课余时刻都值得期待。',idle:'以物会友，给闲置一个继续发光的机会。',lostfound:'让遗失的物品，和焦急的心情，都找到归处。'}[type],link(type+'/publish','发布'+(type==='activity'?'活动':type==='idle'?'闲置':'信息'),'btn primary','plus'))+(type==='lostfound'?`<div class="hint" style="display:flex;align-items:center;gap:12px">${icon('ai')}<span style="flex:1">试试 AI 智能匹配，描述物品特征，发现可能的拾到记录。</span>${btn('帮我找找','lost-match','','btn small')}</div>`:'')+`<div class="toolbar"><div class="tabs" style="margin:0">${cats.map(c=>btn(c,'filter',`data-value="${c}"`,'tab '+(filter===c?'active':''))).join('')}</div><form data-form="filter" style="display:flex;gap:8px;margin-left:auto"><input name="q" aria-label="搜索列表" placeholder="搜索名称或地点" value="${esc(query)}"><button class="btn">搜索</button></form></div>`+listCards(items,type)+`<div class="table-footer"><span>共 ${items.length} 条信息 · 演示数据</span><span>第 1 页</span></div>`;}
function detail(type,id){let item=getItem(type,id);if(!item)return empty('内容不存在','请通过左侧导航选择其他内容。');const key=type+':'+id,fav=state.favorites.includes(key);return head(item.title,`${labels[type]} / 详情`,link(type,'返回列表','btn'),type.toUpperCase())+`<div class="columns"><article class="panel"><img class="detail-cover" src="assets/images/${esc(item.image)}" alt="${esc(item.title)}"><div style="display:flex;gap:8px">${tag(item.category)}${tag(item.status,'orange')}</div><h2 class="spaced">${type==='activity'?'关于这场活动':'物品说明'}</h2><p class="detail-copy">${esc(item.description)}</p><div class="facts"><div><small>${type==='activity'?'活动时间':'发布时间'}</small><b>${esc(item.time)}</b></div><div><small>地点</small><b>${esc(item.location)}</b></div>${type==='idle'?`<div><small>期望换物</small><b>${esc(item.exchange)}</b></div>`:''}</div><div class="hint">${type==='activity'?'报名后请留意审核结果；签到入口位于“我的报名”。':type==='idle'?'先沟通互换意向，确认后完成预约与当面互换。':'请提供只有失主知道的物品特征，保护个人信息。'}</div>${btn(icon('star')+' '+(fav?'已收藏':'收藏'),'favorite',`data-key="${key}"`)} ${btn('举报此内容','report',`data-title="${esc(item.title)}"`,'text-btn')}</article><aside><div class="panel sticky-panel"><div class="post-top">${avatar(item.host)}<div><b>${esc(item.host)}</b><small>校园用户 · 示例身份</small></div></div>${link('user/1','查看主页','text-btn')}${type==='activity'?`<div class="facts"><div><small>已报名</small><b>${item.count} 人</b></div><div><small>人数上限</small><b>${item.total} 人</b></div></div><div class="progress"><i style="width:${Math.min(item.count/item.total*100,100)}%"></i></div>`:'<p class="detail-copy">站内沟通，连接更近一点。</p>'}<div class="stack">${type==='activity'?btn(state.signups.some(x=>String(x.id)===id)?'查看报名记录':item.status==='已满员'?'名额已满':'立即报名','signup',`data-id="${id}" ${item.status==='已满员'?'disabled':''}`,'btn primary'):type==='idle'?btn('预约互换','appointment',`data-id="${id}"`,'btn primary'):btn(item.category==='寻找失物'?'提供线索':'申请认领','claim',`data-id="${id}"`,'btn primary')}${link('chat/1','联系发布者','btn','social')}</div></div></aside></div>`;}
function publish(type){const editing=new URLSearchParams(location.hash.split('?')[1]||'').get('edit');const old=editing?getItem(type,editing):null;return head((old?'编辑':'发布')+(labels[type]||'校园动态'),'分享真实信息，让校园里的连接更简单。',link(type==='post'?'social':type,'返回列表','btn'),'SHARE SOMETHING GOOD')+`<div class="columns"><form class="panel" data-form="publish" data-type="${type}" data-id="${editing||''}">${field('标题 *','title','text',old?.title||'', 'required maxlength="60" placeholder="给它起一个清晰、温暖的标题"')}${field('分类','category','select',old?.category||'',type==='activity'?['文艺','运动','公益','学习']:type==='idle'?['数码','出行','运动']:type==='lostfound'?['寻找失物','拾到物品']:['校园日常','学习交流'])}${field('详细描述 *','description','textarea',old?.description||'','required maxlength="2000" placeholder="介绍具体内容、参与方式或物品特征…"')}${type==='idle'?field('期望换物','exchange','text',old?.exchange||'','required placeholder="希望换到什么物品？"'):''}${type!=='post'?field('地点 *','location','text',old?.location||'','required placeholder="例如：图书馆二楼"'):''}${type==='activity'?`<div class="field-row">${field('开始时间 *','start','datetime-local','2026-09-25T18:30','required')}${field('结束时间 *','end','datetime-local','2026-09-25T21:00','required')}</div><div class="field-row">${field('报名截止 *','deadline','datetime-local','2026-09-24T23:00','required')}${field('人数上限 *','total','number','120','required min="1" max="2000"')}</div>`:''}${type==='lostfound'?`<div class="field-row">${field('发生时间','occurred','datetime-local','2026-09-17T10:30')}${field('联系方式','contact','text','站内私信')}</div>`:''}<label class="upload">${icon('plus')}<br>上传封面图片 <small class="muted">（仅本地预览；演示记录使用内置封面）</small><input type="file" accept="image/*" data-preview="cover-preview"><img id="cover-preview" alt="封面预览" hidden></label><div class="form-actions">${btn(icon('ai')+' AI 帮写','compose','','btn')}${link(type==='post'?'social':type,'取消','btn')}<button class="btn primary">提交审核</button></div></form><aside><div class="panel"><div class="eyebrow">A LITTLE REMINDER</div><h3>让分享更容易被看见</h3><p class="detail-copy">01　标题清晰，突出关键信息。<br>02　图片真实，描述准确。<br>03　沟通友善，尊重彼此。</p><div class="hint">发布后进入待审核状态。审核通过后，内容才会公开展示。</div></div></aside></div>`;}
function social(){const posts=[...state.posts,...CAMPUS.social];return head('动态广场','分享日常的微光，也遇见与你同频的人。',link('social/publish','分享此刻','btn primary','plus'),'MOMENTS ON CAMPUS')+`<div class="columns"><section>${posts.map(p=>`<article class="feed-post"><div class="post-top">${avatar(p.host)}<div>${link('user/1',esc(p.host),'text-btn')}<small>${p.time} · ${p.category} ${p.status?tag(p.status,'orange'):''}</small></div>${btn('举报','report',`data-title="${esc(p.title)}"`,'text-btn')}</div><h3>${esc(p.title)}</h3><p class="detail-copy" style="margin-bottom:0">${esc(p.description)}</p>${p.image?`<img class="post-image" src="assets/images/${esc(p.image)}" alt="${esc(p.title)}" loading="lazy">`:''}<div class="post-actions">${btn(icon('heart')+' '+(p.likes+(state.likes.includes(p.id)?1:0)),'like',`data-id="${p.id}"`,'text-btn '+(state.likes.includes(p.id)?'liked':''))}${btn(icon('social')+' 评论 '+(state.comments[p.id]?.length||0),'comment',`data-id="${p.id}"`,'text-btn')}</div>${(state.comments[p.id]||[]).map(c=>`<div class="comment"><b>${esc(state.profile.name)}</b>：${esc(c)}</div>`).join('')}</article>`).join('')}</section><aside><div class="panel study-panel"><div class="eyebrow">MAKE A CONNECTION</div><h3>今天有什么新鲜事？</h3><p>不必盛大，日常的小美好也值得被记住。</p>${link('social/publish','记录我的校园日常','btn')}</div><div class="panel"><h3>社区小约定</h3><p class="detail-copy">真实分享，友善交流。<br>尊重原创，保护隐私。<br>遇到不当内容，随时举报。</p></div></aside></div>`;}
function notices(id){const all=[...state.notices,...CAMPUS.notices.filter(n=>!state.notices.some(s=>s.id===n.id))];if(id){const n=all.find(x=>String(x.id)===id);return n?head(n.title,n.date+' · '+n.type,link('notice','返回公告'))+`<article class="panel"><p class="detail-copy">${esc(n.body)}</p><p style="text-align:right">校园服务中心<br>${n.date}</p></article>`:empty('公告不存在');}return head('校园公告','校园里的重要信息，一处掌握。','', 'CAMPUS BULLETIN')+`<div class="panel">${all.map(n=>`<a class="notice-row" href="${href('notice/detail/'+n.id)}"><span class="tag">${n.type}</span><span style="flex:1"><b>${esc(n.title)}</b><small>${n.date} · 校园服务中心</small></span>${icon('arrow')}</a>`).join('')}</div>`;}
function messages(){return head('消息中心','重要提醒，及时送达。',btn(state.read?'全部已读':'全部标为已读','read','','btn'))+`<div class="panel">${[['活动通知','秋日草坪音乐节即将开放签到','前往“我的报名”查看活动信息。','activity/my-signup'],['系统通知','欢迎来到梧桐校园','一起发现校园生活的更多可能。','home'],['互动通知','陈同学发来一条私信','你好，你发布的物品还可以互换吗？','chat/1']].map(([t,h,p,r])=>`<a class="notice-row" href="${href(r)}"><span class="symbol">${icon('bell')}</span><span style="flex:1"><b>${h} ${!state.read?tag('未读','orange'):''}</b><small>${p}</small></span><small>${t}<br>09.17</small></a>`).join('')}</div>`;}
function chat(){return head('私信聊天','从一句你好，开始校园里的新连接。','', 'STAY CONNECTED')+`<div class="chat-layout"><aside class="chat-list"><h3>最近会话</h3>${['陈同学','校园音乐社'].map(n=>`<button class="chat-contact ${chatPerson===n?'active':''}" data-action="contact" data-name="${n}">${avatar(n)}<span><b>${n}</b><small>${n==='陈同学'?'关于机械键盘的互换':'活动报名咨询'}</small></span></button>`).join('')}</aside><section class="chat-main"><div class="chat-heading"><b>${chatPerson}</b>${btn('举报会话','report',`data-title="与${chatPerson}的私信"`,'text-btn')}</div><div class="chat-messages" id="messages"><div class="hint">${chatPerson==='陈同学'?'关联物品：九成新机械键盘 · 茶轴':'关联活动：秋日草坪音乐节'} · ${link(chatPerson==='陈同学'?'idle/detail/1':'activity/detail/1','查看详情','text-btn')}</div><div class="bubble">${chatPerson==='陈同学'?'你好，键盘还在，可以先聊聊你的互换意向。':'你好，活动报名已开放，期待在现场见到你！'}</div>${state.chat.filter(m=>m.person===chatPerson).map(m=>`<div class="bubble mine">${esc(m.text)}</div>`).join('')}</div><form class="chat-composer" data-form="chat"><input name="message" aria-label="私信内容" placeholder="输入消息，按 Enter 发送…" required maxlength="1000"><button class="btn primary">发送 ${icon('send')}</button></form><div class="ai-disclaimer">本地聊天演示 · 不会向真实用户发送消息</div></section></div>`;}
function ai(){const messages=state.ai.filter(m=>m.scene===aiScene);return head('AI 学习助手','把难题拆小一点，让成长再近一点。','', 'A LITTLE HELP, A BIG DIFFERENCE')+`<div class="tabs">${['学习答疑','PDF 问答','校园向导'].map(t=>btn(t,'ai-scene',`data-value="${t}"`,'tab '+(aiScene===t?'active':''))).join('')}</div><div class="chat-layout"><aside class="chat-list">${btn(icon('plus')+' 新建对话','new-ai','','btn')}<div class="micro-title">当前学习空间</div><button class="chat-contact active"><span>${icon('ai')}</span><span><b>${aiScene}</b><small>一起探索，慢慢理解</small></span></button><div class="spaced">${link('ai/code','代码纠错 ↗','text-btn')}</div><div>${link('ai/wrong','打开我的错题本 ↗','text-btn')}</div></aside><section class="chat-main"><div class="chat-messages" id="messages">${messages.length?messages.map(m=>`<div class="bubble ${m.role==='user'?'mine':''}">${esc(m.text)}</div>`).join(''):`<div class="ai-welcome"><div class="ai-logo">${icon('ai')}</div><div class="eyebrow">HELLO, CURIOUS MIND</div><h2>${aiScene==='校园向导'?'校园大小事，问问我。':aiScene==='PDF 问答'?'带着问题，读懂每一页。':'今天，我们一起学点什么？'}</h2><p>${aiScene==='PDF 问答'?'选择一份学习资料，开始围绕文档提问。':'无论是一个公式，还是一个突然冒出的好奇。'}</p>${aiScene==='PDF 问答'?'<label class="upload spaced">选择 PDF 文件<input type="file" accept=".pdf,application/pdf" id="pdf-file"><span id="pdf-name" class="muted"></span></label>':`<div class="prompts">${(aiScene==='校园向导'?['本周有什么校园活动？','图书馆什么时候开放？','哪里可以找失物？','怎样预约闲置物品？']:['讲解乘积求导法则','帮我规划一周复习','解释二叉树前序遍历','怎样高效整理错题？']).map(t=>btn(t,'prompt',`data-text="${t}"`,'btn')).join('')}</div>`}</div>`}</div><form class="chat-composer" data-form="ai"><input name="question" aria-label="向 AI 提问" placeholder="${aiScene==='PDF 问答'?'选择 PDF 后，输入你的问题…':'输入你的问题…'}" required maxlength="1500"><button class="btn primary" aria-label="发送问题">${icon('arrow')}</button></form><div class="ai-disclaimer">AI 内容为预设示例，不调用模型；PDF 仅展示文件名，不解析文档。</div></section></div>`;}
function codePage(){return head('代码纠错','看见问题，也理解问题背后的原因。','', 'LEARN BY DEBUGGING')+`<div class="columns"><form class="panel" data-form="code">${field('编程语言','language','select','JavaScript',['JavaScript','Python','Java','C++'])}${field('待分析代码','code','textarea','function sum(a, b) {\n  return a - b;\n}\nconsole.log(sum(2, 3));','required class="code" spellcheck="false"')}${field('错误现象与预期结果','problem','textarea','预期得到 5，实际返回 -1。','required')}<div class="form-actions"><button class="btn primary">${icon('ai')} 分析这段代码</button></div></form><aside><div class="panel"><h3>纠错思路</h3><p class="detail-copy">01　还原错误现象<br>02　定位问题所在<br>03　提供修复方案<br>04　解释相关知识点</p><div class="hint">演示仅对内置加法示例提供预设分析。其他代码会显示待接入提示。</div></div></aside></div>`;}
function wrongBook(){let items=state.wrong.filter(x=>(filter==='全部'||x.subject===filter)&&(!query||x.title.includes(query)));return head('我的错题本','每一个曾经卡住的地方，都可以成为进步的起点。',btn(icon('plus')+' 收录错题','wrong-add','','btn primary'),'SMALL STEPS, REAL PROGRESS')+`<div class="stat-grid">${[['累计收录',state.wrong.length,'记录每一次思考'],['待复习',state.wrong.filter(x=>x.status==='待复习').length,'今天再理解一点'],['已掌握',state.wrong.filter(x=>x.status==='已掌握').length,'把知识变成自己的'],['覆盖学科',new Set(state.wrong.map(x=>x.subject)).size,'连接不同的知识']].map(([l,n,s])=>`<div class="stat"><small>${l}</small><strong>${n}</strong><em>${s}</em></div>`).join('')}</div><div class="toolbar"><div class="tabs" style="margin:0">${['全部',...new Set(state.wrong.map(x=>x.subject))].map(s=>btn(s,'filter',`data-value="${s}"`,'tab '+(filter===s?'active':''))).join('')}</div>${btn('薄弱点 / 复习计划','study-plan','','btn small')}</div><div class="panel">${items.length?items.map((q,i)=>`<div class="wrong-row"><span class="index">${String(i+1).padStart(2,'0')}</span><div class="wrong-main"><h3>${esc(q.title)}</h3>${tag(q.subject)} <span style="font-size:11px;color:var(--muted)">${esc(q.point)}</span></div>${tag(q.status,q.status==='待复习'?'orange':'')}${btn('开始复习','review',`data-id="${q.id}"`,'btn small')}${btn('删除','delete-wrong',`data-id="${q.id}"`,'text-btn')}</div>`).join(''):empty()}</div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(c=>`<tr>${c.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty('暂无记录','完成对应操作后，记录将在这里显示。')}</td></tr>`}</tbody></table></div>`;}
function personal(which){let body;if(which==='signup')body=table(['活动名称','状态','时间','操作'],state.signups.map(x=>[link('activity/detail/'+x.id,esc(getItem('activity',x.id)?.title||x.title),'text-btn'),tag(x.status,x.status==='待审核'?'orange':''),'09.25 · 18:30',x.status==='待审核'?btn('模拟审核通过','signup-approve',`data-id="${x.id}"`,'text-btn'):x.status==='已通过'?btn('活动签到','signin',`data-id="${x.id}"`,'text-btn'):tag('签到完成')]));
else if(which==='appointment')body=table(['物品','互换意向','状态','操作'],state.appointments.map(x=>[esc(getItem('idle',x.id)?.title||'闲置物品'),esc(x.intent),tag(x.status,'orange'),btn(x.status==='待确认'?'模拟对方同意':x.status==='已确认'?'确认互换完成':x.status==='已完成'?'留下评价':'查看评价','appointment-next',`data-id="${x.id}"`,'text-btn')]));
else if(which==='claim')body=table(['物品','认领说明','状态','操作'],state.claims.map(x=>[esc(getItem('lostfound',x.id)?.title||'失物信息'),esc(x.proof),tag(x.status,'orange'),x.status==='已完成'?tag('物归原主'):btn(x.status==='待审核'?'模拟审核通过':'确认领取','claim-next',`data-id="${x.id}"`,'text-btn')]));
return head({signup:'我的报名',appointment:'我的预约',claim:'我的认领'}[which],'演示操作会保存在当前浏览器中。',which==='signup'?btn('导出报名名单','export-signups','','btn'):'')+`<div class="hint">本页提供“模拟审核”以便独立演示流程；实际系统中由发布者审核。</div><div class="panel">${body}</div>`;}
function profile(other=false){let body='';if(!other){if(profileTab==='我的发布')body=table(['内容标题','类型','状态','操作'],state.publications.map(p=>[esc(p.title),labels[p.type],tag(p.status,'orange'),link(p.type+'/publish?edit='+p.id,'编辑','text-btn')+' '+btn(p.status==='已下架'?'重新上架':'下架','publication-status',`data-id="${p.id}"`,'text-btn')]));else if(profileTab==='我的收藏'){const items=state.favorites.map(k=>{const [type,id]=k.split(':');return {type,item:getItem(type,id)};}).filter(x=>x.item);body=items.length?`<div class="cards">${items.map(x=>card(x.item,x.type)).join('')}</div>`:empty('还没有收藏','在详情页点击收藏，把喜欢的校园内容留在这里。');}else body=`<div class="quick-grid">${[['activity/my-signup','activity','我的报名'],['idle/appointments','idle','我的预约'],['lostfound/claims','lost','我的认领'],['ai/wrong','book','我的错题']].map(([p,i,l])=>`<a class="quick" href="${href(p)}">${icon(i)}${l}</a>`).join('')}</div>`;}
return head(other?'同学主页':'个人中心',other?'从共同的兴趣开始，认识校园里的新朋友。':'记录你的学习，也收藏校园里的每一份热爱。','', 'YOUR CAMPUS STORY')+`<div class="profile-hero">${avatar(other?'陈':state.profile.name)}<div><h1>${other?'陈同学':esc(state.profile.name)}</h1><p>计算机科学与技术 · 2023 级</p><p>${other?'喜欢音乐、骑行与有趣的旧物。':esc(state.profile.bio)}</p>${tag('校园用户')}</div>${other?link('chat/1','发私信','btn primary','social'):btn('编辑资料','edit-profile','','btn')}</div>${other?listCards(CAMPUS.idle.slice(0,2),'idle','two'):`<div class="tabs line">${['我的发布','我的收藏','我的事务'].map(t=>btn(t,'profile-tab',`data-value="${t}"`,'tab '+(profileTab===t?'active':''))).join('')}</div><div class="panel">${body}</div><div style="display:flex;gap:15px">${btn('修改密码','password','','text-btn')}${link('login','退出演示身份','text-btn')}</div>`}`;}
function searchPage(){const groups=['activity','idle','lostfound','social'];const found=groups.flatMap(t=>visibleItems(t).filter(x=>searchable(x).includes(query)).map(x=>({type:t,item:x})));return head('搜索结果',query?`“${esc(query)}” · 找到 ${found.length} 条校园内容`:'输入关键词，发现你感兴趣的校园内容。')+`<form class="toolbar" data-form="search"><input name="q" placeholder="搜索活动、闲置、失物、动态" aria-label="搜索词" value="${esc(query)}"><button class="btn primary">搜索</button></form><div class="panel">${found.length?found.map(({type,item})=>`<a class="notice-row" href="${href(type==='social'?'social':type+'/detail/'+item.id)}">${tag(labels[type]||'校园动态')}<div><b>${esc(item.title)}</b><small>${esc(item.description.slice(0,75))}</small></div></a>`).join(''):empty('没有找到匹配的内容','试试“音乐”“图书馆”或“键盘”。')}</div>`;}
function auth(register=false){document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('admin',ADMIN);app.innerHTML=`<main class="auth"><section class="auth-story"><a href="${href(ADMIN?'dashboard':'home')}" class="brand"><span class="brandmark">w</span><span><b>梧桐校园</b><small>WUTONG CAMPUS</small></span></a><div><div class="eyebrow" style="color:#c8d6bb">A CAMPUS FULL OF POSSIBILITIES</div><h1>让每一份热爱，<br>在这里生根。</h1><p>学习、生活与新朋友。你的校园故事，从梧桐开始。</p></div><small>梧桐校园 · AI 校园综合服务平台</small></section><section class="auth-form"><form class="auth-card" data-form="auth" data-register="${register}"><a class="text-btn" href="${href(ADMIN?'dashboard':'home')}">← 返回${ADMIN?'管理工作台':'校园首页'}</a><div class="eyebrow spaced">${ADMIN?'ADMIN WORKSPACE':'WELCOME TO WUTONG'}</div><h1>${register?'开启你的校园故事':'欢迎回到梧桐'}</h1><p>${ADMIN?'管理员演示登录':register?'创建账号，连接你的校园生活。':'登录账号，继续发现校园里的小美好。'}</p>${field(ADMIN?'管理员账号':'学号','account','text',ADMIN?'demo-admin':'2023001001','required minlength="3"')}${register?field('昵称','nickname','text','','required maxlength="32"'):''}${field('密码','password','password','','required minlength="6" placeholder="演示：输入任意 6 位以上字符"')}${register?field('确认密码','confirm','password','','required minlength="6"'):''}<label class="field"><span>验证码</span><div class="captcha"><input name="captcha" aria-label="验证码答案" required placeholder="输入右侧运算结果"><button type="button" data-action="captcha" id="captcha" data-answer="12" aria-label="刷新验证码">7 + 5</button></div></label>${ADMIN?field('演示角色','role','select','超级管理员',['超级管理员','内容管理员']):''}<label class="check"><input type="checkbox" required>我已知悉：此页面为本地原型，不验证真实账号</label><button class="btn primary">${register?'创建演示账号':'进入'+(ADMIN?'管理工作台':'我的校园')}</button><div class="auth-foot">${ADMIN?'<a href="index.html">返回学生端</a>':link(register?'login':'register',register?'已有账号？立即登录':'还没有账号？创建账号','text-btn')}</div></form></section></main>`;}
function dashboard(){return head('校园运行，一目了然','欢迎回来。今天也一起守护有温度的校园社区。',`<span class="tag">● 系统运行正常 · 示例</span>`,'CAMPUS AT A GLANCE')+`<div class="stat-grid">${[['注册用户','2,846','较上周 +12.8%'],['校园内容','1,392','本周新增 86 条'],['待审核',Object.values(state.audits).length<8?8-Object.values(state.audits).length:0,'请及时处理内容'],['AI 今日调用','326','成功率 98.6%']].map(([l,n,s])=>`<div class="stat"><small>${l}</small><strong>${n}</strong><em>${s}</em></div>`).join('')}</div><div class="columns"><div class="panel"><div class="section-title"><h2>校园活跃趋势</h2><span class="tag">最近 7 天 · 示例</span></div><p style="font-size:11px">每日活跃用户</p><div class="chart" role="img" aria-label="最近七天活跃用户：128、156、139、188、172、205、226">${[128,156,139,188,172,205,226].map((n,i)=>`<div class="chart-bar" style="height:${n*.72}px"><span>${n}</span><small>09.${11+i}</small></div>`).join('')}</div></div><div class="panel"><h3>内容类型分布</h3><div class="donut" role="img" aria-label="动态45%，活动27%，闲置17%，失物11%"><div class="donut-inner"><b>1,392</b><small>累计校园内容</small></div></div><div class="legend"><span>● 动态 45%</span><span>● 活动 27%</span><span>● 闲置 17%</span><span>● 失物 11%</span></div></div></div><div class="panel"><div class="section-title"><h2>待办事项</h2>${link('audit/activity','进入审核中心 ↗','text-btn')}</div>${table(['内容','类型','提交人','AI 初审','操作'],CAMPUS.activity.slice(0,3).map(x=>[x.title,tag('校园活动'),x.host,tag('建议通过'),link('audit/activity','去审核','text-btn')]))}</div>`;}
function adminAudit(type){const actual=type==='post'?'social':type;const items=getItems(actual).filter(x=>!query||x.title.includes(query));return head(({activity:'活动',idle:'闲置',lostfound:'失物招领',post:'动态'}[type])+'审核','结合 AI 初审结果，完成内容质量与安全审核。','', 'CONTENT REVIEW')+`<div class="hint">AI 审核仅作辅助，最终审核结果以人工操作为准。本页修改演示记录。</div><div class="panel">${table(['内容标题','发布人','提交时间','审核状态','操作'],items.map(x=>{const status=state.audits[type+':'+x.id]||'待审核';return [esc(x.title),esc(x.host),'2026-09-17',tag(status,status==='待审核'?'orange':status==='已驳回'?'red':''),btn('查看','audit-detail',`data-type="${type}" data-id="${x.id}"`,'text-btn')+(status==='待审核'?btn('通过','audit-approve',`data-key="${type+':'+x.id}"`,'text-btn')+btn('驳回','audit-reject',`data-key="${type+':'+x.id}"`,'text-btn'):'')];}))}</div>`;}
function adminUsers(admins=false){const users=admins?[['超级管理员','demo-admin','super'],['内容管理员','content-demo','admin']]:[['林同学','2023001001','计算机学院'],['陈同学','2023001002','艺术学院'],['周同学','2023001003','信息学院']];return head(admins?'管理员管理':'用户管理',admins?'维护管理员身份与权限范围。':'查看校园用户信息与账号状态。',admins?btn('新增管理员','add-admin','','btn primary'):'')+`<div class="panel">${table(['用户','账号',admins?'角色':'所属院系','状态','操作'],[...users,...(admins?(state.admins||[]):[])].filter(u=>!query||u.join('').includes(query)).map(([n,id,r])=>[esc(n),esc(id),r,tag(state.users[id]||'正常',state.users[id]==='已封禁'?'red':''),id==='demo-admin'?tag('当前账号'):btn(state.users[id]==='已封禁'?'解除封禁':'封禁','ban',`data-id="${id}" data-name="${esc(n)}"`,'text-btn')]))}</div>`;}
function adminContent(){return head('内容管理','统一维护校园内容，查看报名与签到记录。',btn('导出签到报表','export-signups','','btn'))+`<div class="tabs">${['全部','活动','闲置','失物','动态'].map(t=>btn(t,'filter',`data-value="${t}"`,'tab '+(filter===t?'active':''))).join('')}</div><div class="panel">${table(['标题','类型','发布人','状态','操作'],['activity','idle','lostfound','social'].flatMap(t=>getItems(t).map(x=>({t,x}))).filter(({t,x})=>(filter==='全部'||({activity:'活动',idle:'闲置',lostfound:'失物',social:'动态'}[t])===filter)&&(!query||x.title.includes(query))).map(({t,x})=>[esc(x.title),labels[t]||'动态',esc(x.host),tag(state.audits['content:'+t+':'+x.id]||'已发布'),btn('查看','audit-detail',`data-type="${t}" data-id="${x.id}"`,'text-btn')+btn(state.audits['content:'+t+':'+x.id]==='已下架'?'恢复':'下架','content-toggle',`data-key="content:${t}:${x.id}"`,'text-btn')]))}</div>`;}
function adminReports(){return head('举报处理','认真对待每一条反馈，维护友善的校园环境。')+`<div class="panel">${table(['举报内容','举报原因','举报人','状态','操作'],[{id:1,title:'闲置物品描述与实物不一致',reason:'信息不实',name:'王同学'},{id:2,title:'动态评论包含不友善内容',reason:'不当言论',name:'许同学'},...(state.submittedReports||[])].filter(x=>!query||x.title.includes(query)).map(x=>[esc(x.title),esc(x.reason),esc(x.name),tag(state.reports[x.id]||'待处理','orange'),state.reports[x.id]?tag('已发送处理通知'):btn('处理举报','handle-report',`data-id="${x.id}"`,'text-btn')]))}</div>`;}
function adminNotices(edit=false,id){if(edit){const existing=[...state.notices,...CAMPUS.notices].find(n=>String(n.id)===id);return head(existing?'编辑公告':'发布公告','向校园传递准确、及时的重要信息。',link('notice','返回列表'))+`<form class="panel" data-form="notice" data-id="${id||''}">${field('公告标题 *','title','text',existing?.title||'','required maxlength="80"')}${field('类型','type','select',existing?.type||'校园通知',['校园通知','服务公告','社区倡议'])}${field('公告正文 *','body','textarea',existing?.body||'','required')}<div class="form-actions"><button class="btn primary">保存公告</button></div></form>`;}
return head('公告管理','维护平台公告与校园服务通知。',link('notice/edit','发布公告','btn primary','plus'))+`<div class="panel">${table(['公告标题','类型','日期','操作'],[...state.notices,...CAMPUS.notices].filter(n=>!state.notices.some(s=>s.id===n.id&&s!==n)).filter(n=>!query||n.title.includes(query)).map(n=>[esc(n.title),tag(n.type),n.date,link('notice/edit/'+n.id,'编辑','text-btn')]))}</div>`;}
function aiAudit(){return head('AI 内容审核','查看机器审核建议与人工复核结果。')+`<div class="panel">${table(['内容','识别结果','风险等级','处理状态','操作'],[['图书馆约自习','正常校园交流','低风险'],['闲置互换联系方式','建议检查个人信息','中风险'],['校园动态评论','可能存在不当措辞','高风险']].filter(x=>!query||x.join('').includes(query)).map(([t,r,l],i)=>[t,r,tag(l,i===2?'red':i===1?'orange':''),tag(state.audits['ai:'+i]||'待复核'),btn('人工复核','ai-review',`data-id="${i}" data-title="${t}"`,'text-btn')]))}</div>`;}
function aiConfig(){return head('AI 服务配置','统一管理模型连接与场景提示词。')+`<form class="panel" data-form="ai-config"><div class="hint">配置仅保存在原型中。请勿输入真实 API Key，原型不会调用外部服务。</div><div class="field-row">${field('接口地址','url','url',state.settings.url||'https://api.example.com/v1','required')}${field('模型名称','model','text',state.settings.model||'deepseek-chat','required')}</div>${field('API Key（演示占位）','key','password','','placeholder="仅演示，不保存此字段"')}${field('学习答疑提示词','prompt','textarea',state.settings.prompt||'你是一位耐心的校园学习助手。请分步骤讲解，启发学生独立思考。')}<div class="form-actions">${btn('检查格式','check-ai','','btn')}<button class="btn primary">保存演示配置</button></div></form>`;}
function aiLogs(){return head('AI 调用日志','追踪请求状态与用量，了解服务运行情况。')+`<div class="panel">${table(['时间','场景','模型','耗时','Token','结果'],[['09:42:16','学习答疑','1.2s','628','成功'],['09:38:05','校园向导','0.9s','420','成功'],['09:35:29','代码纠错','2.4s','1,052','成功'],['09:30:12','PDF 问答','30s','0','超时']].filter(x=>!query||x.join('').includes(query)).map(([t,s,d,k,r])=>[t,s,'deepseek-chat',d,k,tag(r,r==='超时'?'red':'')]))}<div class="table-footer">以上日志均为演示样本，不代表真实模型调用。</div></div>`;}
function settings(){return head('系统配置','调整校园服务平台的基础设置。')+`<form class="panel" data-form="settings">${field('站点名称','siteName','text',state.settings.siteName||'梧桐校园','required')}<label class="switch-line"><span><b>开放用户注册</b><small>允许新用户创建校园账号</small></span><input type="checkbox" name="registration" ${state.settings.registration!==false?'checked':''}></label><label class="switch-line"><span><b>维护模式</b><small>在原型中保存开关；下方可单独预览维护页面</small></span><input type="checkbox" name="maintenance" ${state.settings.maintenance?'checked':''}></label><div class="switch-line"><span><b>维护页面预览</b><small>不影响真实站点，也不会阻断原型演示</small></span><a class="btn small" href="index.html#/maintenance">打开预览</a></div><div class="form-actions"><button class="btn primary">保存设置</button></div></form>`;}
const extraStudent=[['activity/detail/1','活动详情'],['activity/publish','活动发布'],['activity/my-signup','我的报名 / 签到'],['idle/detail/1','闲置详情'],['idle/publish','发布闲置'],['idle/appointments','预约 / 完成 / 评价'],['lostfound/detail/1','失物详情'],['lostfound/publish','发布失物信息'],['lostfound/claims','认领 / 确认领取'],['social/publish','发布动态'],['notice/detail/1','公告详情'],['user/1','他人主页'],['search','全局搜索'],['login','登录'],['register','注册'],['maintenance','维护页面']];
function sitemap(){return head('原型页面导航','每个入口均可直接访问，也可复制地址中的 # 路由交给其他 AI。')+`<div class="hint">HTML / CSS / JavaScript · 无框架依赖 · 无真实账号与接口 · 交接文档见 docs 文件夹</div><div class="page-map">${(ADMIN?adminNav:studentNav).flatMap(g=>g[1].map(([p,i,n])=>[p,n])).concat(ADMIN?[['login','管理员登录'],['notice/edit','公告编辑']]:extraStudent).map(([p,n])=>`<a class="map-link" href="${href(p)}">${n}<small>#/${p}</small></a>`).join('')}</div>`;}
function render(){const raw=route(),path=raw.split('?')[0],parts=path.split('/');document.title=(ADMIN?'管理工作台':'梧桐校园')+' · HTML 交互原型';if(path==='login'||path==='register'){auth(path==='register');return;}let html,title;
if(ADMIN){if(state.role!=='super'&&path.startsWith('system')){html=empty('当前角色无权访问','请在登录页选择超级管理员演示身份。');title='权限提示';}else if(path==='dashboard'){html=dashboard();title='数据总览';}else if(parts[0]==='audit'){html=adminAudit(parts[1]||'activity');title='内容审核';}else if(path==='user'||path==='system'){html=adminUsers(path==='system');title=path==='system'?'管理员管理':'用户管理';}else if(path==='content'){html=adminContent();title='内容管理';}else if(path==='report'){html=adminReports();title='举报处理';}else if(parts[0]==='notice'){html=adminNotices(parts[1]==='edit',parts[2]);title='公告管理';}else if(path==='ai/audit'){html=aiAudit();title='AI 内容审核';}else if(path==='ai/config'){html=aiConfig();title='AI 服务配置';}else if(path==='ai/logs'){html=aiLogs();title='AI 调用日志';}else if(path==='system/config'){html=settings();title='系统配置';}}
else {if(path==='home'){html=home();title='校园首页';}else if(labels[parts[0]]){const type=parts[0];title=labels[type];html=parts[1]==='detail'?detail(type,parts[2]):parts[1]==='publish'?publish(type):parts[1]==='my-signup'?personal('signup'):parts[1]==='appointments'?personal('appointment'):parts[1]==='claims'?personal('claim'):catalog(type);}else if(parts[0]==='social'){html=parts[1]==='publish'?publish('post'):social();title='动态广场';}else if(parts[0]==='notice'){html=notices(parts[2]);title='校园公告';}else if(path==='message'){html=messages();title='消息中心';}else if(parts[0]==='chat'){html=chat();title='私信聊天';}else if(path==='ai/chat'){html=ai();title='AI 学习助手';}else if(path==='ai/code'){html=codePage();title='代码纠错';}else if(path==='ai/wrong'){html=wrongBook();title='我的错题本';}else if(path==='profile'||parts[0]==='user'){html=profile(parts[0]==='user');title='个人中心';}else if(path==='search'){query=new URLSearchParams(raw.split('?')[1]||'').get('q')||query;html=searchPage();title='搜索结果';}else if(path==='maintenance'){html=`<div class="panel">${empty('校园服务正在小憩','系统维护中，请稍后回来。感谢你的耐心等待。')}<div style="text-align:center">${link('home','返回原型首页','btn primary')}</div></div>`;title='维护页面';}}
if(path==='sitemap'){html=sitemap();title='页面导航';}if(!html){html=empty('页面暂未找到','请通过页面导航选择有效入口。')+link('sitemap','查看全部页面');title='页面未找到';}shell(html,title);if(path.startsWith('chat')||path==='ai/chat'){const messages=document.getElementById('messages');if(messages)messages.scrollTop=messages.scrollHeight;}}
function openModal(title,body){lastFocus=document.activeElement;modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn(icon('close'),'close','aria-label="关闭弹窗"','icon-btn')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();if(lastFocus?.isConnected)lastFocus.focus();}
function formModal(title,form,fields,extra='',submit='确认提交'){openModal(title,`<form data-form="${form}" ${extra}>${fields}<div class="form-actions">${btn('取消','close')}<button class="btn primary">${submit}</button></div></form>`);}
function resultModal(title,text){openModal(title,`<p class="detail-copy">${esc(text).replace(/\n/g,'<br>')}</p><div class="form-actions">${btn('知道了','close','','btn primary')}</div>`);}
function syncPublication(key,approved){const [type,id]=key.split(':');const item=[...state.publications,...state.posts].find(x=>String(x.id)===id);if(item)item.status=approved?({activity:'报名中',idle:'可预约',lostfound:'待认领',post:'已发布'}[type]||'已发布'):'已驳回';}
function commit(message){save();closeModal();render();toast(message);}
function aiAnswer(question){const q=question.trim();let response;if(aiScene==='校园向导')response=/图书馆/.test(q)?'图书馆开放时间示例为 08:00—22:00。假期安排请查看校园公告。':/失物/.test(q)?'前往“失物招领”，按物品名称或地点搜索；也可以试试 AI 智能匹配示例。':/闲置|预约/.test(q)?'打开闲置详情，填写互换意向并提交预约，等待发布者确认后再安排见面。':'本周推荐：秋日草坪音乐节（9 月 25 日）、三对三篮球赛（10 月 8 日）。请到校园活动页面查看报名详情。';else if(aiScene==='PDF 问答')response='已展示你的提问。此原型不读取 PDF 内容；真实实现需要上传文档、绑定会话并调用 PDF 问答接口。';else if(/求导/.test(q))response='乘积求导法则：(uv)′ = u′v + uv′。\n例如 f(x)=x·eˣ，取 u=x，v=eˣ。\n所以 f′(x)=1·eˣ+x·eˣ=(1+x)eˣ。\n试着自己求一下 x²·eˣ 的导数吧。';else if(/二叉树/.test(q))response='前序遍历顺序：根节点、左子树、右子树。\n递归先判断节点是否为空，再访问当前节点并依次递归两个子树。';else response='可以分成三个小步骤：\n1. 先列出问题中已经知道的条件。\n2. 找到不理解的知识点，用一道简单例题验证。\n3. 自己复述解法，并把易错点收进错题本。';state.ai.push({scene:aiScene,role:'user',text:q},{scene:aiScene,role:'assistant',text:'【预设演示回答】\n'+response});save();render();}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const {action,id,key,type,value}=target.dataset;
switch(action){
case 'menu':document.getElementById('sidebar').classList.toggle('open');break;
case 'theme':state.theme=state.theme==='dark'?'light':'dark';save();document.documentElement.dataset.theme=state.theme;break;
case 'close':closeModal();break;
case 'reset':openModal('重置演示数据',`<p>清除本原型的本地收藏、报名、发布和模拟记录，恢复初始状态。不会修改源项目。</p><div class="form-actions">${btn('取消','close')}${btn('确认重置','reset-confirm','','btn danger')}</div>`);break;
case 'reset-confirm':try{localStorage.removeItem(STORE);}catch{}location.reload();break;
case 'publish-menu':openModal('想分享些什么？',`<div class="quick-grid">${[['activity/publish','activity','发起活动'],['idle/publish','idle','发布闲置'],['lostfound/publish','lost','发布失物'],['social/publish','social','发布动态']].map(([p,i,l])=>`<a class="quick" href="${href(p)}" data-action="close">${icon(i)}${l}</a>`).join('')}</div>`);break;
case 'filter':case 'home-tab':filter=value;render();break;
case 'profile-tab':profileTab=value;render();break;
case 'favorite':state.favorites=state.favorites.includes(key)?state.favorites.filter(k=>k!==key):[...state.favorites,key];save();render();toast(state.favorites.includes(key)?'已加入收藏':'已取消收藏');break;
case 'signup':if(state.signups.some(x=>String(x.id)===id)){go('activity/my-signup');break;}formModal('报名参加活动','signup',`<div class="hint">${esc(getItem('activity',id).title)}</div>${field('姓名 *','name','text',state.profile.name,'required')}${field('联系方式 *','contact','text','','required placeholder="手机号或站内联系方式"')}${field('报名说明','remark','textarea','','placeholder="简单介绍你的参与意向"')}`,`data-id="${id}"`,'提交报名');break;
case 'signup-approve':state.signups.find(x=>String(x.id)===id).status='已通过';save();render();toast('模拟审核通过，现在可以体验签到');break;
case 'signin':formModal('活动签到','signin',`<div class="hint">演示签到码：WT2026。真实签到应验证后端签名二维码。</div>${field('签到码 *','code','text','','required placeholder="输入 WT2026"')}`,`data-id="${id}"`,'确认签到');break;
case 'appointment':if(state.appointments.some(x=>String(x.id)===id)){go('idle/appointments');break;}formModal('预约互换','appointment',`${field('互换意向 *','intent','textarea','','required placeholder="介绍你想用来互换的物品"')}${field('期望见面时间 *','time','datetime-local','2026-09-18T17:00','required')}`,`data-id="${id}"`,'提交预约');break;
case 'appointment-next':{const x=state.appointments.find(x=>String(x.id)===id);if(x.status==='已评价'){resultModal('互换评价',x.review);break;}if(x.status==='已完成'){formModal('评价这次互换','review-idle',field('评价 *','review','textarea','','required maxlength="300"'),`data-id="${id}"`);break;}x.status=x.status==='待确认'?'已确认':'已完成';save();render();toast('状态已更新：'+x.status);break;}
case 'claim':if(state.claims.some(x=>String(x.id)===id)){go('lostfound/claims');break;}formModal('认领 / 提供线索','claim',`${field('物品特征或线索 *','proof','textarea','','required placeholder="例如容量、独特标记、丢失地点，请勿填写敏感个人信息"')}${field('联系方式 *','contact','text','站内私信','required')}`,`data-id="${id}"`);break;
case 'claim-next':{const x=state.claims.find(x=>String(x.id)===id);x.status=x.status==='待审核'?'已通过':'已完成';save();render();toast('认领状态已更新');break;}
case 'lost-match':formModal('AI 智能匹配','lost-match',`<p>描述物品特征，预览基于关键词的本地匹配示例。</p>${field('物品描述 *','description','textarea','','required placeholder="例如：银色 U 盘，图书馆丢失"')}`,'','查找线索');break;
case 'like':{const n=Number(id);state.likes=state.likes.includes(n)?state.likes.filter(x=>x!==n):[...state.likes,n];save();render();break;}
case 'comment':formModal('留下你的回应','comment',field('评论内容 *','content','textarea','','required maxlength="500"'),`data-id="${id}"`,'发布评论');break;
case 'report':formModal('举报内容','report',`<p>举报对象：${esc(target.dataset.title)}</p>${field('原因','reason','select','信息不实',['信息不实','不当言论','广告推广','侵犯隐私','其他'])}${field('补充说明 *','detail','textarea','','required maxlength="500"')}`,`data-title="${esc(target.dataset.title)}"`,'提交举报');break;
case 'read':state.read=true;save();render();toast('所有消息已标为已读');break;
case 'contact':chatPerson=target.dataset.name;render();break;
case 'ai-scene':aiScene=value;render();break;
case 'prompt':aiAnswer(target.dataset.text);break;
case 'new-ai':state.ai=state.ai.filter(x=>x.scene!==aiScene);save();render();break;
case 'wrong-add':formModal('收录一道错题','wrong-add',`${field('学科','subject','select','高等数学',['高等数学','数据结构','大学英语','其他'])}${field('题目内容 *','title','textarea','','required')}${field('正确答案 / 解析 *','answer','textarea','','required')}${field('知识点','point','text','','placeholder="记录这道题考察的知识"')}<label class="upload">拍照 / 图片录入（仅预览，OCR 待接入）<input type="file" accept="image/*" data-preview="ocr-preview"><img id="ocr-preview" alt="错题图片预览" hidden></label>`,'','保存错题');break;
case 'review':{const q=state.wrong.find(x=>String(x.id)===id);openModal('复习 · '+esc(q.subject),`<h3>${esc(q.title)}</h3><details class="panel spaced"><summary>展开答案与解析</summary><p class="detail-copy">${esc(q.answer)}</p></details><div class="hint">知识点：${esc(q.point)}</div><div class="form-actions">${btn('还需练习','master',`data-id="${id}" data-status="待复习"`)}${btn('生成同类题','practice',`data-id="${id}"`)}${btn('我已掌握','master',`data-id="${id}" data-status="已掌握"`,'btn primary')}</div>`);break;}
case 'master':state.wrong.find(x=>String(x.id)===id).status=target.dataset.status;commit('复习状态已记录');break;
case 'practice':{const q=state.wrong.find(x=>String(x.id)===id);resultModal('同类题 · 预设示例',q.subject==='高等数学'?'求 g(x) = x² · eˣ 的导数。\n参考答案：g′(x) = (2x+x²)eˣ。\n先独立推导，再与答案核对。':'请用自己的话解释“'+q.point+'”，再设计一个具体例子验证。\n这是预设演示任务，真实同类题需要 AI 接口生成。');break;}
case 'delete-wrong':openModal('删除这道错题？',`<p>仅删除本地演示记录。</p><div class="form-actions">${btn('取消','close')}${btn('删除','delete-wrong-confirm',`data-id="${id}"`,'btn danger')}</div>`);break;
case 'delete-wrong-confirm':state.wrong=state.wrong.filter(x=>String(x.id)!==id);commit('错题已删除');break;
case 'study-plan':openModal('薄弱点与复习计划',`<div class="hint">根据当前错题状态生成的本地计划，非 AI 分析结果。</div>${state.wrong.filter(x=>x.status==='待复习').map((q,i)=>`<div class="notice-row"><span class="tag">${i+1}</span><span><b>${esc(q.point||q.title)}</b><small>建议 15 分钟：回顾知识点、独立作答、对照解析。</small></span></div>`).join('')||'<p>当前没有待复习错题，继续保持！</p>'}<div class="form-actions">${btn('开始复习','close','','btn primary')}</div>`);break;
case 'edit-profile':formModal('编辑个人资料','profile',field('昵称 *','name','text',state.profile.name,'required maxlength="32"')+field('个人简介','bio','textarea',state.profile.bio,'maxlength="255"'));break;
case 'password':formModal('修改密码','password',field('原密码','old','password','','required minlength="6"')+field('新密码','new','password','','required minlength="6"')+field('确认新密码','confirm','password','','required minlength="6"'));break;
case 'publication-status':{const p=state.publications.find(x=>String(x.id)===id);p.status=p.status==='已下架'?'待审核':'已下架';save();render();toast('内容状态已更新');break;}
case 'compose':{const f=target.closest('form'),title=f.elements.title.value.trim();if(!title){f.elements.title.focus();toast('先填写标题，再生成示例草稿');break;}f.elements.description.value=`【AI 帮写示例】${title}。欢迎感兴趣的同学了解详情，请提前沟通具体安排。请在发布前核对并补充真实信息。`;toast('已填入预设示例，请按实际情况修改');break;}
case 'captcha':{const a=Math.ceil(Math.random()*9),b=Math.ceil(Math.random()*9);target.textContent=`${a} + ${b}`;target.dataset.answer=a+b;break;}
case 'export-signups':{const rows=[['活动','姓名','联系方式','状态'],...state.signups.map(s=>[getItem('activity',s.id)?.title||'',s.name,s.contact,s.status])];download('梧桐校园-报名签到演示.csv','\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('演示名单已导出');break;}
case 'audit-detail':{const t=type==='post'?'social':type,x=getItem(t,id);if(!x){toast('未找到内容');break;}openModal('内容详情',`<img class="detail-cover" src="assets/images/${esc(x.image)}" alt="${esc(x.title)}"><h3>${esc(x.title)}</h3><p class="detail-copy">${esc(x.description)}</p>${tag('AI 初审：建议人工确认')}<div class="form-actions">${btn('关闭','close')}${btn('审核通过','audit-approve',`data-key="${type}:${id}"`,'btn primary')}</div>`);break;}
case 'audit-approve':state.audits[key]='已通过';syncPublication(key,true);commit('审核通过，已更新演示记录');break;
case 'audit-reject':formModal('驳回内容','audit-reject',field('驳回原因 *','reason','textarea','','required placeholder="说明需修改的内容"'),`data-key="${key}"`,'确认驳回');break;
case 'content-toggle':state.audits[key]=state.audits[key]==='已下架'?'已发布':'已下架';save();render();toast('内容状态已更新');break;
case 'ban':if(state.users[id]==='已封禁'){state.users[id]='正常';save();render();toast('已解除演示账号封禁');}else formModal('封禁账号 · '+esc(target.dataset.name),'ban',field('处置原因 *','reason','textarea','','required'),`data-id="${id}"`,'确认封禁');break;
case 'handle-report':formModal('处理举报','handle-report',field('处理结果','result','select','警告并通知',['警告并通知','下架相关内容','封禁账号','举报不成立'])+field('处理说明 *','reason','textarea','','required'),`data-id="${id}"`,'提交处理结果');break;
case 'ai-review':formModal('人工复核 · '+esc(target.dataset.title),'ai-review',field('复核结果','result','select','人工通过',['人工通过','人工拦截'])+field('复核备注','reason','textarea'),`data-id="${id}"`);break;
case 'add-admin':formModal('新增演示管理员','add-admin',field('姓名 *','name','text','','required')+field('账号 *','account','text','','required pattern="[a-zA-Z0-9_-]{3,30}"')+field('角色','role','select','内容管理员',['内容管理员','超级管理员']));break;
case 'check-ai':{const f=target.closest('form');if(f.reportValidity())toast('配置格式通过；原型未发送连通性请求');break;}
}
});
function download(name,content,mime){const url=URL.createObjectURL(new Blob([content],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',event=>{const f=event.target;if(!f.dataset.form)return;event.preventDefault();const data=Object.fromEntries(new FormData(f));for(const k of Object.keys(data))if(typeof data[k]==='string')data[k]=data[k].trim();const id=f.dataset.id;
switch(f.dataset.form){
case 'search':query=data.q;filter='全部';if(ADMIN)render();else go('search?q='+encodeURIComponent(query));break;
case 'filter':query=data.q;render();break;
case 'auth':if(data.captcha!==f.querySelector('#captcha').dataset.answer){toast('验证码错误，请重新计算');break;}if(f.dataset.register==='true'&&data.password!==data.confirm){toast('两次输入的密码不一致');break;}if(data.nickname)state.profile.name=data.nickname;if(ADMIN)state.role=data.role==='超级管理员'?'super':'admin';save();go(ADMIN?'dashboard':'home');toast('已进入本地演示身份');break;
case 'signup':state.signups.push({id,...data,status:'待审核'});save();closeModal();go('activity/my-signup');toast('报名已提交，等待发布者审核');break;
case 'signin':if(data.code.toUpperCase()!=='WT2026'){toast('签到码错误，请输入 WT2026');break;}state.signups.find(x=>String(x.id)===id).status='已签到';commit('签到成功，祝你玩得开心');break;
case 'appointment':state.appointments.push({id,...data,status:'待确认'});save();closeModal();go('idle/appointments');toast('预约已提交');break;
case 'review-idle':Object.assign(state.appointments.find(x=>String(x.id)===id),{review:data.review,status:'已评价'});commit('感谢你的评价');break;
case 'claim':state.claims.push({id,...data,status:'待审核'});save();closeModal();go('lostfound/claims');toast('申请已提交');break;
case 'lost-match':{const terms=data.description.split(/[，,。\s]+/).filter(Boolean);const found=CAMPUS.lostfound.filter(x=>terms.some(t=>x.title.includes(t)||x.description.includes(t)||t.includes('U盘')&&x.title.includes('U 盘')||t.includes('U 盘')&&x.title.includes('U 盘')||t.includes('学生卡')&&x.title.includes('学生卡')||t.includes('图书馆')&&x.location.includes('图书馆')));openModal('匹配结果 · 关键词演示',found.length?`<p>以下为本地关键词匹配示例，请核对物品特征。</p>${found.map(x=>`<a class="notice-row" href="${href('lostfound/detail/'+x.id)}" data-action="close"><span><b>${x.title}</b><small>${x.location}</small></span>${icon('arrow')}</a>`).join('')}`:empty('暂未发现相近记录','尝试输入“银色 U 盘”或“学生卡”。'));break;}
case 'comment':(state.comments[id]??=[]).push(data.content);commit('评论已发布');break;
case 'report':(state.submittedReports??=[]).push({id:Date.now(),title:f.dataset.title,reason:data.reason,name:state.profile.name,detail:data.detail});commit('举报已记录，可在管理端查看演示记录');break;
case 'chat':if(!data.message){toast('消息不能为空');break;}state.chat.push({person:chatPerson,text:data.message});save();render();app.querySelector('[name=message]')?.focus();break;
case 'ai':if(data.question)aiAnswer(data.question);break;
case 'code':if(data.language==='JavaScript'&&data.code.includes('return a - b'))openModal('代码分析 · 预设示例',`<div class="hint">发现逻辑错误：sum 使用了减法运算符。</div><pre class="code-result">function sum(a, b) {\n  return a + b;\n}\nconsole.log(sum(2, 3)); // 5</pre><p class="spaced">将减号改为加号，即可实现示例中的求和需求。</p>`);else resultModal('待接入真实代码分析','已展示代码纠错输入流程。当前代码不属于内置示例，需接入 /api/ai/code-fix 后才能生成可靠分析。');break;
case 'wrong-add':state.wrong.unshift({id:Date.now(),...data,status:'待复习'});commit('错题已收录');break;
case 'profile':state.profile={name:data.name,bio:data.bio};commit('个人资料已更新');break;
case 'password':if(data.new!==data.confirm){toast('两次新密码不一致');break;}closeModal();toast('密码表单校验通过；原型不保存或修改真实密码');break;
case 'publish':{const type=f.dataset.type;if(type==='activity'&&(data.end<=data.start||data.deadline>data.start)){toast('结束时间须晚于开始时间，报名截止不得晚于开始时间');break;}const item={...data,id:id?Number(id):Date.now(),type,host:state.profile.name,image:{activity:'01-活动海报.png',idle:'02-机械键盘.png',lostfound:'04-银色U盘.png',post:'05-校园晚霞.png'}[type],time:type==='activity'?data.start.replace('T',' · '):'刚刚',location:data.location||'校园',status:'待审核',count:0,total:Number(data.total)||0,likes:0};if(type==='post'){state.posts.unshift(item);save();go('social');toast('动态已保存到个人演示流，状态为待审核');}else{if(id)state.publications=state.publications.filter(p=>String(p.id)!==id);state.publications.unshift(item);save();profileTab='我的发布';go('profile');toast('已提交审核，可在我的发布中继续编辑');}break;}
case 'audit-reject':state.audits[f.dataset.key]='已驳回';syncPublication(f.dataset.key,false);(state.auditReasons??={})[f.dataset.key]=data.reason;commit('内容已驳回，原因已保存');break;
case 'ban':state.users[id]='已封禁';commit('演示账号已封禁');break;
case 'handle-report':state.reports[id]=data.result;commit('处理结果已保存（演示通知）');break;
case 'ai-review':state.audits['ai:'+id]=data.result;commit('人工复核完成');break;
case 'add-admin':if(['demo-admin','content-demo',...(state.admins||[]).map(x=>x[1])].includes(data.account)){toast('账号已存在');break;}(state.admins??=[]).push([data.name,data.account,data.role==='超级管理员'?'super':'admin']);commit('演示管理员已创建');break;
case 'notice':{const n={id:id?Number(id):Date.now(),title:data.title,type:data.type,body:data.body,date:'2026-09-17'};state.notices=state.notices.filter(x=>x.id!==n.id);state.notices.unshift(n);save();go('notice');toast('公告已保存');break;}
case 'ai-config':Object.assign(state.settings,{url:data.url,model:data.model,prompt:data.prompt});save();toast('演示配置已保存，API Key 未存储');break;
case 'settings':Object.assign(state.settings,{siteName:data.siteName,registration:!!data.registration,maintenance:!!data.maintenance});save();toast('本地演示设置已保存');break;
}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-preview]')){const file=e.target.files[0],img=document.getElementById(e.target.dataset.preview);if(!file)return;if(!file.type.startsWith('image/')){toast('请选择图片文件');return;}const old=img.dataset.url;if(old)URL.revokeObjectURL(old);const url=URL.createObjectURL(file);img.src=url;img.dataset.url=url;img.hidden=false;}if(e.target.id==='pdf-file'){const file=e.target.files[0];document.getElementById('pdf-name').textContent=file?'已选择：'+file.name+'（演示，不解析）':'';}});
modal.addEventListener('click',e=>{if(e.target===modal){const b=modal.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{closeModal();filter='全部';query='';render();window.scrollTo(0,0);});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.querySelector('.top-search input')?.focus();}});
render();

window.addEventListener('storage',e=>{if(e.key===STORE&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(incoming.version===1){state=incoming;render();}}catch{}}});
